#include "stdlib/stats/strided/scurange.h"
#include "stdlib/math/base/assert/is_nan.h"
#include "stdlib/blas/base/shared.h"
#include "stdlib/strided/base/stride2offset.h"

/**
* Computes the cumulative range of a single-precision floating-point strided array.
*
* @param N        number of indexed elements
* @param X        input array
* @param strideX  stride length for X
* @param Y        output array
* @param strideY  stride length for Y
*/
void API_SUFFIX(stdlib_strided_scurange)( const CBLAS_INT N, const float *X, const CBLAS_INT strideX, float *Y, const CBLAS_INT strideY ) {
	const CBLAS_INT ox = stdlib_strided_stride2offset( N, strideX );
	const CBLAS_INT oy = stdlib_strided_stride2offset( N, strideY );
	API_SUFFIX(stdlib_strided_scurange_ndarray)( N, X, strideX, ox, Y, strideY, oy );
	return;
}

/**
* Computes the cumulative range of a single-precision floating-point strided array
* using alternative indexing semantics.
*
* @param N        number of indexed elements
* @param X        input array
* @param strideX  stride length for X
* @param offsetX  starting index for X
* @param Y        output array
* @param strideY  stride length for Y
* @param offsetY  starting index for Y
*/
void API_SUFFIX(stdlib_strided_scurange_ndarray)( const CBLAS_INT N, const float *X, const CBLAS_INT strideX, const CBLAS_INT offsetX, float *Y, const CBLAS_INT strideY,const CBLAS_INT offsetY) {
	CBLAS_INT ix;
	CBLAS_INT iy;
	CBLAS_INT i;
	float min;
	float max;
	float v;

	if ( N <= 0 ) {
		return;
	}

	ix = offsetX;
	iy = offsetY;

	v = X[ ix ];
	Y[ iy ] = 0.0;

	if ( stdlib_base_is_nan( v ) ) {
		for ( i = 1; i < N; i++ ) {
			iy += strideY;
			Y[ iy ] = v;
		}
		return;
	}

	min = v;
	max = v;

	for ( i = 1; i < N; i++ ) {
		ix += strideX;
		iy += strideY;
		v = X[ ix ];

		if ( stdlib_base_is_nan( v ) ) {
			Y[ iy ] = v;
			for ( i += 1; i < N; i++ ) {
				iy += strideY;
				Y[ iy ] = v;
			}
			return;
		}
		if ( v < min ) {
			min = v;
		} else if ( v > max ) {
			max = v;
		}
		Y[ iy ] = max - min;
	}
}
